export interface BuildChatWebSocketUrlInput
{
  pile: string;
  sessionId: string;
  clientId?: string;
  after?: number;
}

export function BuildChatWebSocketUrl(input: BuildChatWebSocketUrlInput): string
{
  const params = new URLSearchParams();
  params.set("p", input.pile);
  params.set("session", input.sessionId);

  if (input.clientId !== undefined && input.clientId.length > 0)
  {
    params.set("client", input.clientId);
  }

  if (input.after !== undefined)
  {
    params.set("after", String(input.after));
  }

  return `/ws/chat?${params.toString()}`;
}

import { randomUUID } from "node:crypto";

export const x_chatEnvelopeVersion = 1;

export interface ChatEnvelope
{
  v: typeof x_chatEnvelopeVersion;
  kind: string;
  id: string;
  pile: string;
  sessionId: string;
  clientId?: string;
  sequence?: number;
  timestamp: string;
  payload?: unknown;
}

export interface CreateChatEnvelopeInput
{
  kind: string;
  pile: string;
  sessionId: string;
  clientId?: string;
  sequence?: number;
  payload?: unknown;
  id?: string;
  timestamp?: string;
}

export function CreateChatEnvelope(input: CreateChatEnvelopeInput): ChatEnvelope
{
  const envelope: ChatEnvelope = {
    v: x_chatEnvelopeVersion,
    kind: input.kind,
    id: input.id ?? randomUUID(),
    pile: input.pile,
    sessionId: input.sessionId,
    timestamp: input.timestamp ?? new Date().toISOString(),
  };

  if (input.clientId !== undefined)
  {
    envelope.clientId = input.clientId;
  }

  if (input.sequence !== undefined)
  {
    envelope.sequence = input.sequence;
  }

  if (input.payload !== undefined)
  {
    envelope.payload = input.payload;
  }

  return envelope;
}

