import { createServer, type Server } from "node:http";
import type { IncomingMessage, ServerResponse } from "node:http";

import type { AgentManager } from "../agents/manager.js";
import { FormatRestError } from "../shared/errors.js";
import type { SheafChatConfig } from "./config.js";
import { x_serviceName, x_serviceVersion } from "./constants.js";
import { SendJson } from "./http.js";
import { DispatchApiRoute } from "./router.js";
import type { RouteContext } from "./routes/context.js";

export { x_serviceName, x_serviceVersion };

export interface SheafChatServerOptions
{
  config: SheafChatConfig;
  bindHost: string;
  bindPort: number;
  agentManager: AgentManager;
}

export interface SheafChatServer
{
  httpServer: Server;
  listen: () => Promise<number>;
  close: () => Promise<void>;
}

function HandleNotFound(response: ServerResponse): void
{
  SendJson(response, 404, FormatRestError("not_found", "route not found"));
}

export function CreateSheafChatServer(options: SheafChatServerOptions): SheafChatServer
{
  const routeContext: RouteContext = {
    config: options.config,
    agentManager: options.agentManager,
  };

  const httpServer = createServer((request: IncomingMessage, response: ServerResponse) =>
  {
    const url = new URL(request.url ?? "/", `http://${request.headers.host ?? "localhost"}`);

    if (url.pathname.startsWith("/api/"))
    {
      void DispatchApiRoute(routeContext, request, response, url);
      return;
    }

    HandleNotFound(response);
  });

  return {
    httpServer,
    listen: () =>
      new Promise<number>((resolve, reject) =>
      {
        httpServer.once("error", reject);
        httpServer.listen(options.bindPort, options.bindHost, () =>
        {
          httpServer.off("error", reject);
          const address = httpServer.address();

          if (address === null || typeof address === "string")
          {
            resolve(options.bindPort);
            return;
          }

          resolve(address.port);
        });
      }),
    close: () =>
      new Promise<void>((resolve, reject) =>
      {
        httpServer.close((error) =>
        {
          if (error)
          {
            reject(error);
            return;
          }

          resolve();
        });
      }),
  };
}

import { EventEmitter } from "node:events";

import type { AgentSessionEvent } from "@earendil-works/pi-coding-agent";

import {
  AgentLifecycleState,
  type ModelReference,
  type SessionManifest,
} from "../shared/types.js";

export interface SessionKey
{
  pile: string;
  sessionId: string;
}

export type ModelApplyTo = "next_turn" | "current_turn";

export interface UserMessageSubmission
{
  messageId: string;
  text: string;
  attachments?: unknown[];
  steer?: boolean;
}

export interface AgentStatusSnapshot
{
  key: SessionKey;
  state: AgentLifecycleState;
  model: ModelReference;
  rootDirectory: string;
  connectedClientCount: number;
  manifestPresent: boolean;
  isStreaming: boolean;
  activeRunCount: number;
  activeToolCount: number;
  manifest?: SessionManifest;
  provisionalRootDirectory?: string;
  error?: string;
}

export type LifecycleEventName =
  | "status"
  | "model"
  | "userMessageAccepted"
  | "agentEvent"
  | "manifestUpdated"
  | "error";

export interface LifecycleStatusEvent
{
  key: SessionKey;
  state: AgentLifecycleState;
  previousState?: AgentLifecycleState;
}

export interface LifecycleModelEvent
{
  key: SessionKey;
  model: ModelReference;
  applyTo: ModelApplyTo;
}

export interface LifecycleUserMessageAcceptedEvent
{
  key: SessionKey;
  message: UserMessageSubmission;
}

export interface LifecycleAgentEvent
{
  key: SessionKey;
  event: AgentSessionEvent;
}

export interface LifecycleManifestUpdatedEvent
{
  key: SessionKey;
  manifest: SessionManifest;
}

export interface LifecycleErrorEvent
{
  key: SessionKey;
  code: string;
  message: string;
  fatal?: boolean;
}

export interface LifecycleEventMap
{
  status: LifecycleStatusEvent;
  model: LifecycleModelEvent;
  userMessageAccepted: LifecycleUserMessageAcceptedEvent;
  agentEvent: LifecycleAgentEvent;
  manifestUpdated: LifecycleManifestUpdatedEvent;
  error: LifecycleErrorEvent;
}

const x_keySeparator = "\u0000";

export function FormatSessionKey(key: SessionKey): string
{
  return `${key.pile}${x_keySeparator}${key.sessionId}`;
}

export function ParseSessionKey(encoded: string): SessionKey
{
  const separatorIndex = encoded.indexOf(x_keySeparator);

  if (separatorIndex < 0)
  {
    throw new Error(`invalid session key: ${encoded}`);
  }

  return {
    pile: encoded.slice(0, separatorIndex),
    sessionId: encoded.slice(separatorIndex + 1),
  };
}

export class LifecycleEmitter extends EventEmitter
{
  EmitStatus(event: LifecycleStatusEvent): void
  {
    this.emit("status", event);
  }

  EmitModel(event: LifecycleModelEvent): void
  {
    this.emit("model", event);
  }

  EmitUserMessageAccepted(event: LifecycleUserMessageAcceptedEvent): void
  {
    this.emit("userMessageAccepted", event);
  }

  EmitAgentEvent(event: LifecycleAgentEvent): void
  {
    this.emit("agentEvent", event);
  }

  EmitManifestUpdated(event: LifecycleManifestUpdatedEvent): void
  {
    this.emit("manifestUpdated", event);
  }

  EmitError(event: LifecycleErrorEvent): void
  {
    if (this.listenerCount("error") === 0)
    {
      return;
    }

    this.emit("error", event);
  }

  On<TEvent extends LifecycleEventName>(
    eventName: TEvent,
    listener: (event: LifecycleEventMap[TEvent]) => void,
  ): () => void
  {
    this.on(eventName, listener);

    return () =>
    {
      this.off(eventName, listener);
    };
  }
}

import type { HistoryPage, HistoryPageRequest, SessionLogEntry } from "../shared/types.js";
import type { ChatEnvelope } from "../shared/envelope.js";
import { StorageError } from "./errors.js";
import { CollectSessionLogEntries } from "./sessionLog.js";
import type { StoragePaths } from "./paths.js";
import { ValidateSessionId } from "./validation.js";

export const x_defaultHistoryLimit = 50;
export const x_maxHistoryLimit = 200;

function ClampHistoryLimit(limit: number | undefined): number
{
  if (limit === undefined || !Number.isFinite(limit) || limit <= 0)
  {
    return x_defaultHistoryLimit;
  }

  return Math.min(Math.floor(limit), x_maxHistoryLimit);
}

function EnvelopesFromEntries(entries: SessionLogEntry[]): ChatEnvelope[]
{
  return entries.map((entry) => entry.envelope);
}

function SequenceBounds(entries: SessionLogEntry[]): {
  oldestSequence: number | null;
  newestSequence: number | null;
}
{
  if (entries.length === 0)
  {
    return {
      oldestSequence: null,
      newestSequence: null,
    };
  }

  return {
    oldestSequence: entries[0].sequence,
    newestSequence: entries[entries.length - 1].sequence,
  };
}

function ValidateHistoryRequest(request: HistoryPageRequest): HistoryPageRequest
{
  const hasBefore = request.before !== undefined;
  const hasAfter = request.after !== undefined;

  if (hasBefore && hasAfter)
  {
    throw new StorageError(
      "invalid_history_request",
      "history request cannot include both before and after cursors",
    );
  }

  return request;
}

function BuildLatestPage(entries: SessionLogEntry[], limit: number): HistoryPage
{
  const pageEntries = entries.slice(Math.max(0, entries.length - limit));
  const bounds = SequenceBounds(pageEntries);
  const allBounds = SequenceBounds(entries);

  return {
    direction: "latest",
    envelopes: EnvelopesFromEntries(pageEntries),
    oldestSequence: bounds.oldestSequence,
    newestSequence: bounds.newestSequence ?? allBounds.newestSequence,
    hasMoreBefore: entries.length > pageEntries.length,
    hasMoreAfter: false,
  };
}

function BuildBeforePage(
  entries: SessionLogEntry[],
  before: number,
  limit: number,
): HistoryPage
{
  const olderEntries = entries.filter((entry) => entry.sequence < before);
  const pageEntries = olderEntries.slice(Math.max(0, olderEntries.length - limit));
  const bounds = SequenceBounds(pageEntries);
  const pageNewest = bounds.newestSequence;
  const hasMoreAfter =
    pageNewest !== null &&
    entries.some((entry) => entry.sequence > pageNewest && entry.sequence < before);

  return {
    direction: "before",
    envelopes: EnvelopesFromEntries(pageEntries),
    oldestSequence: bounds.oldestSequence,
    newestSequence: bounds.newestSequence,
    hasMoreBefore: olderEntries.length > pageEntries.length,
    hasMoreAfter,
  };
}

function BuildAfterPage(
  entries: SessionLogEntry[],
  after: number,
  limit: number,
): HistoryPage
{
  const newerEntries = entries.filter((entry) => entry.sequence > after);
  const pageEntries = newerEntries.slice(0, limit);
  const bounds = SequenceBounds(pageEntries);
  const allBounds = SequenceBounds(entries);

  return {
    direction: "after",
    envelopes: EnvelopesFromEntries(pageEntries),
    oldestSequence: bounds.oldestSequence,
    newestSequence: bounds.newestSequence ?? allBounds.newestSequence,
    hasMoreAfter: newerEntries.length > pageEntries.length,
    hasMoreBefore: false,
  };
}

export async function ReadHistoryPage(
  paths: StoragePaths,
  pile: string,
  sessionId: string,
  request: HistoryPageRequest = {},
): Promise<HistoryPage>
{
  const validatedSessionId = ValidateSessionId(sessionId);
  const validatedRequest = ValidateHistoryRequest(request);
  const limit = ClampHistoryLimit(validatedRequest.limit);
  const entries = await CollectSessionLogEntries(paths, pile, validatedSessionId);

  if (validatedRequest.before !== undefined)
  {
    return BuildBeforePage(entries, validatedRequest.before, limit);
  }

  if (validatedRequest.after !== undefined)
  {
    return BuildAfterPage(entries, validatedRequest.after, limit);
  }

  return BuildLatestPage(entries, limit);
}

import { appendFile, access, readFile, writeFile } from "node:fs/promises";
import { randomUUID } from "node:crypto";
import { createReadStream } from "node:fs";
import readline from "node:readline";

import type { AllocatedSessionShell, ModelReference, SessionLogEntry } from "../shared/types.js";
import type { ChatEnvelope, CreateChatEnvelopeInput } from "../shared/envelope.js";
import { CreateChatEnvelope } from "../shared/envelope.js";
import { StorageError } from "./errors.js";
import { UpdateManifest } from "./manifests.js";
import { EnsurePileExists } from "./piles.js";
import {
  ResolveHistoryFilePath,
  ResolveProvisionalFilePath,
  ResolveRootDirectory,
  ResolveSessionFilePath,
  type StoragePaths,
} from "./paths.js";
import { ValidateSessionId } from "./validation.js";

export const x_defaultExtensionVersion = "0.1.0";

interface ProvisionalSessionRecord
{
  rootDirectory: string;
  model: ModelReference;
  createdAt: string;
}

const x_sequenceLocks = new Map<string, Promise<void>>();

function SessionKey(pile: string, sessionId: string): string
{
  return `${pile}\u0000${sessionId}`;
}

async function WithSessionLock<T>(
  pile: string,
  sessionId: string,
  operation: () => Promise<T>,
): Promise<T>
{
  const key = SessionKey(pile, sessionId);
  const previous = x_sequenceLocks.get(key) ?? Promise.resolve();
  let release!: () => void;
  const current = new Promise<void>((resolve) =>
  {
    release = resolve;
  });
  const tail = previous.then(() => current);
  x_sequenceLocks.set(key, tail);

  await previous;

  try
  {
    return await operation();
  }
  finally
  {
    release();
    if (x_sequenceLocks.get(key) === tail)
    {
      x_sequenceLocks.delete(key);
    }
  }
}

function ParseSessionLogEntry(line: string): SessionLogEntry | null
{
  const trimmed = line.trim();

  if (trimmed.length === 0)
  {
    return null;
  }

  try
  {
    return JSON.parse(trimmed) as SessionLogEntry;
  }
  catch
  {
    return null;
  }
}

export async function ReadAllSessionLogEntries(
  paths: StoragePaths,
  pile: string,
  sessionId: string,
): Promise<SessionLogEntry[]>
{
  const historyPath = ResolveHistoryFilePath(paths, pile, sessionId);

  let raw: string;

  try
  {
    raw = await readFile(historyPath, "utf8");
  }
  catch
  {
    return [];
  }

  const entries: SessionLogEntry[] = [];

  for (const line of raw.split("\n"))
  {
    const entry = ParseSessionLogEntry(line);

    if (entry !== null)
    {
      entries.push(entry);
    }
  }

  entries.sort((left, right) => left.sequence - right.sequence);
  return entries;
}

export async function ReadLatestSequence(
  paths: StoragePaths,
  pile: string,
  sessionId: string,
): Promise<number>
{
  const entries = await ReadAllSessionLogEntries(paths, pile, sessionId);

  if (entries.length === 0)
  {
    return 0;
  }

  return entries[entries.length - 1].sequence;
}

async function StreamSessionLogEntries(
  historyPath: string,
  onEntry: (entry: SessionLogEntry) => void | Promise<void>,
): Promise<void>
{
  try
  {
    await access(historyPath);
  }
  catch
  {
    return;
  }

  const stream = createReadStream(historyPath, { encoding: "utf8" });
  const lineReader = readline.createInterface({
    input: stream,
    crlfDelay: Infinity,
  });

  try
  {
    for await (const line of lineReader)
    {
      const entry = ParseSessionLogEntry(line);

      if (entry !== null)
      {
        await onEntry(entry);
      }
    }
  }
  finally
  {
    lineReader.close();
    stream.destroy();
  }
}

export async function AllocateSessionShell(
  paths: StoragePaths,
  pile: string,
  rootDirectory: string,
  model: ModelReference,
): Promise<AllocatedSessionShell>
{
  await EnsurePileExists(paths, pile);
  const sessionId = ValidateSessionId(randomUUID().replace(/-/g, ""));
  const absoluteRoot = ResolveRootDirectory(paths.repoRoot, rootDirectory);
  const sessionFilePath = ResolveSessionFilePath(paths, pile, sessionId);
  const historyFilePath = ResolveHistoryFilePath(paths, pile, sessionId);
  const provisionalFilePath = ResolveProvisionalFilePath(paths, pile, sessionId);
  const provisionalRecord: ProvisionalSessionRecord = {
    rootDirectory: absoluteRoot,
    model,
    createdAt: new Date().toISOString(),
  };

  await writeFile(sessionFilePath, "", "utf8");
  await writeFile(historyFilePath, "", "utf8");
  await writeFile(
    provisionalFilePath,
    `${JSON.stringify(provisionalRecord, null, 2)}\n`,
    "utf8",
  );

  return {
    pile,
    sessionId,
    provisionalSession: {
      rootDirectory: absoluteRoot,
      model,
    },
    sessionFilePath,
    historyFilePath,
  };
}

export interface AppendEnvelopeInput extends Omit<CreateChatEnvelopeInput, "sequence">
{
  sequence?: number;
}

export async function AppendEnvelope(
  paths: StoragePaths,
  pile: string,
  sessionId: string,
  input: AppendEnvelopeInput,
): Promise<ChatEnvelope>
{
  const validatedSessionId = ValidateSessionId(sessionId);

  return WithSessionLock(pile, validatedSessionId, async () =>
  {
    const historyPath = ResolveHistoryFilePath(paths, pile, validatedSessionId);
    const latestSequence = await ReadLatestSequence(paths, pile, validatedSessionId);
    const sequence = input.sequence ?? latestSequence + 1;

    if (sequence <= latestSequence)
    {
      throw new StorageError(
        "invalid_sequence",
        `sequence ${sequence} is not greater than latest ${latestSequence}`,
      );
    }

    const envelope = CreateChatEnvelope({
      ...input,
      pile,
      sessionId: validatedSessionId,
      sequence,
    });
    const entry: SessionLogEntry = {
      sequence,
      envelope,
    };

    await appendFile(historyPath, `${JSON.stringify(entry)}\n`, "utf8");

    try
    {
      await UpdateManifest(paths, pile, validatedSessionId, {
        lastSequence: sequence,
      });
    }
    catch (error)
    {
      if (!(error instanceof StorageError && error.code === "manifest_not_found"))
      {
        throw error;
      }
    }

    return envelope;
  });
}

export async function CollectSessionLogEntries(
  paths: StoragePaths,
  pile: string,
  sessionId: string,
): Promise<SessionLogEntry[]>
{
  const historyPath = ResolveHistoryFilePath(paths, pile, sessionId);
  const entries: SessionLogEntry[] = [];

  await StreamSessionLogEntries(historyPath, (entry) =>
  {
    entries.push(entry);
  });

  entries.sort((left, right) => left.sequence - right.sequence);
  return entries;
}

import type { AguiEvent, AguiSnapshotMessage } from "./types.js";

interface ToolCallSnapshot
{
  id: string;
  name: string;
  args: string;
  result: string | null;
}

interface SnapshotBuilderState
{
  messages: Map<string, AguiSnapshotMessage>;
  order: string[];
  finalizedIds: Set<string>;
  openText: Map<string, { role: string; content: string; timestamp?: number }>;
  openReasoning: Map<string, { content: string; timestamp?: number }>;
  openTools: Map<string, ToolCallSnapshot>;
  toolParents: Map<string, string>;
  toolResults: Map<string, string>;
}

function CreateSnapshotState(): SnapshotBuilderState
{
  return {
    messages: new Map(),
    order: [],
    finalizedIds: new Set(),
    openText: new Map(),
    openReasoning: new Map(),
    openTools: new Map(),
    toolParents: new Map(),
    toolResults: new Map(),
  };
}

function TrackFirstSeen(state: SnapshotBuilderState, messageId: string): void
{
  if (!state.order.includes(messageId))
  {
    state.order.push(messageId);
  }
}

function UpsertMessage(state: SnapshotBuilderState, message: AguiSnapshotMessage): void
{
  const messageId = String(message.id);
  TrackFirstSeen(state, messageId);
  state.messages.set(messageId, message);
}

function FinalizeAssistantToolCalls(state: SnapshotBuilderState, parentMessageId: string): ToolCallSnapshot[]
{
  const toolCalls: ToolCallSnapshot[] = [];

  for (const [toolCallId, toolCall] of state.openTools.entries())
  {
    if (state.toolParents.get(toolCallId) !== parentMessageId)
    {
      continue;
    }

    toolCalls.push({
      id: toolCallId,
      name: toolCall.name,
      args: toolCall.args,
      result: state.toolResults.get(toolCallId) ?? toolCall.result,
    });
  }

  return toolCalls;
}

function ApplyAguiEvent(state: SnapshotBuilderState, event: AguiEvent): void
{
  const eventType = event.type;

  if (eventType === "TEXT_MESSAGE_START")
  {
    const messageId = String(event.messageId);

    if (state.finalizedIds.has(messageId))
    {
      return;
    }

    TrackFirstSeen(state, messageId);
    state.openText.set(messageId, {
      role: String(event.role ?? "assistant"),
      content: "",
      timestamp: typeof event.timestamp === "number" ? event.timestamp : undefined,
    });
    return;
  }

  if (eventType === "TEXT_MESSAGE_CONTENT")
  {
    const messageId = String(event.messageId);

    if (state.finalizedIds.has(messageId))
    {
      return;
    }

    const open = state.openText.get(messageId) ?? {
      role: "assistant",
      content: "",
    };
    open.content += String(event.delta ?? "");
    state.openText.set(messageId, open);
    return;
  }

  if (eventType === "TEXT_MESSAGE_END")
  {
    const messageId = String(event.messageId);

    if (state.finalizedIds.has(messageId))
    {
      return;
    }

    const open = state.openText.get(messageId);

    if (open === undefined)
    {
      return;
    }

    const snapshot: AguiSnapshotMessage = {
      id: messageId,
      role: open.role,
      content: open.content,
    };

    if (open.timestamp !== undefined)
    {
      snapshot.timestamp = open.timestamp;
    }

    if (open.role === "assistant")
    {
      const toolCalls = FinalizeAssistantToolCalls(state, messageId);

      if (toolCalls.length > 0)
      {
        snapshot.toolCalls = toolCalls.map((toolCall) => ({
          id: toolCall.id,
          name: toolCall.name,
          args: toolCall.args,
          result: toolCall.result,
        }));
      }
    }

    UpsertMessage(state, snapshot);
    state.finalizedIds.add(messageId);
    state.openText.delete(messageId);
    return;
  }

  if (eventType === "REASONING_MESSAGE_START")
  {
    const messageId = String(event.messageId);

    if (state.finalizedIds.has(messageId))
    {
      return;
    }

    TrackFirstSeen(state, messageId);
    state.openReasoning.set(messageId, {
      content: "",
      timestamp: typeof event.timestamp === "number" ? event.timestamp : undefined,
    });
    return;
  }

  if (eventType === "REASONING_MESSAGE_CONTENT")
  {
    const messageId = String(event.messageId);
    const open = state.openReasoning.get(messageId) ?? { content: "" };
    open.content += String(event.delta ?? "");
    state.openReasoning.set(messageId, open);
    return;
  }

  if (eventType === "REASONING_MESSAGE_END")
  {
    const messageId = String(event.messageId);
    const open = state.openReasoning.get(messageId);

    if (open === undefined)
    {
      return;
    }

    const snapshot: AguiSnapshotMessage = {
      id: messageId,
      role: "reasoning",
      content: open.content,
    };

    if (open.timestamp !== undefined)
    {
      snapshot.timestamp = open.timestamp;
    }

    UpsertMessage(state, snapshot);
    state.finalizedIds.add(messageId);
    state.openReasoning.delete(messageId);
    return;
  }

  if (eventType === "TOOL_CALL_START")
  {
    const toolCallId = String(event.toolCallId);

    if (event.parentMessageId !== undefined)
    {
      TrackFirstSeen(state, String(event.parentMessageId));
    }

    state.openTools.set(toolCallId, {
      id: toolCallId,
      name: String(event.toolCallName ?? "tool"),
      args: "",
      result: null,
    });

    if (event.parentMessageId !== undefined)
    {
      state.toolParents.set(toolCallId, String(event.parentMessageId));
    }

    return;
  }

  if (eventType === "TOOL_CALL_ARGS")
  {
    const toolCallId = String(event.toolCallId);
    const toolCall = state.openTools.get(toolCallId);

    if (toolCall !== undefined)
    {
      toolCall.args += String(event.delta ?? "");
    }

    return;
  }

  if (eventType === "TOOL_CALL_RESULT")
  {
    const toolCallId = String(event.toolCallId);
    const messageId = String(event.messageId ?? `${toolCallId}:result`);
    const content = String(event.content ?? "");
    state.toolResults.set(toolCallId, content);

    const snapshot: AguiSnapshotMessage = {
      id: messageId,
      role: "tool",
      content,
      toolCallId,
    };

    if (typeof event.timestamp === "number")
    {
      snapshot.timestamp = event.timestamp;
    }

    UpsertMessage(state, snapshot);
    return;
  }

  if (eventType === "CUSTOM")
  {
    const messageId = String(event.messageId ?? `custom:${state.order.length + 1}`);
    UpsertMessage(state, {
      id: messageId,
      role: "activity",
      activityType: String(event.name ?? "custom"),
      content: typeof event.value === "string" ? event.value : JSON.stringify(event.value ?? {}),
    });
    return;
  }

  if (eventType === "RAW")
  {
    const messageId = String(event.messageId ?? `raw:${state.order.length + 1}`);
    UpsertMessage(state, {
      id: messageId,
      role: "activity",
      activityType: String(event.source ?? "raw"),
      content: JSON.stringify(event.event ?? {}),
    });
    return;
  }

  if (eventType === "ACTIVITY_SNAPSHOT")
  {
    const messageId = String(event.messageId ?? `activity:${state.order.length + 1}`);
    UpsertMessage(state, {
      id: messageId,
      role: "activity",
      activityType: String(event.activityType ?? "activity"),
      content: JSON.stringify(event.content ?? {}),
    });
  }
}

export function eventsToSnapshots(events: AguiEvent[]): AguiSnapshotMessage[]
{
  const state = CreateSnapshotState();

  for (const event of events)
  {
    ApplyAguiEvent(state, event);
  }

  const dedupedOrder: string[] = [];
  const seen = new Set<string>();

  for (const messageId of state.order)
  {
    if (seen.has(messageId))
    {
      continue;
    }

    seen.add(messageId);
    dedupedOrder.push(messageId);
  }

  return dedupedOrder
    .map((messageId) => state.messages.get(messageId))
    .filter((message): message is AguiSnapshotMessage => message !== undefined);
}

