async function SendHello(
  client: ConnectedClient,
  context: ChatWebSocketContext,
  params: ChatWebSocketConnectParams,
  broadcaster: Awaited<ReturnType<SessionBroadcasterRegistry["GetOrCreate"]>>,
): Promise<void>
