  if (params.after !== undefined)
  {
    await broadcaster.ReplayAfter(client.connectionId, params.after);
  }

  const caughtUp = CreateChatEnvelope({
    kind: x_serverCaughtUpKind,
    pile: params.pile,
    sessionId: params.sessionId,
    clientId: params.clientId,
    payload: {},
