    {
      await CollectEnvelopesUntil(socket, "server.caught_up");

      SendClientFrame(
        socket,
        CreateClientEnvelope(
          "client.model_select",
          session.pile,
          session.sessionId,
          {
            provider: model.provider,
            id: model.id,
            applyTo: "next_turn",
          },
        ),
      );

      const modelChanged = await WaitForEnvelope(
        socket,
        (envelope) => envelope.kind === "model.changed",
      );

      assert.deepEqual(
