        socket,
        CreateClientEnvelope(
          "client.user_message",
          session.pile,
          session.sessionId,
          { messageId: "concurrent-b", text: "B" },
        ),
      );

      const first = await WaitForEnvelope(
        socket,
        (envelope) =>
          envelope.kind === "chat.user_message" &&
          (envelope.payload as { messageId?: string }).messageId === "concurrent-a",
      );
      const second = await WaitForEnvelope(
        socket,
        (envelope) =>
          envelope.kind === "chat.user_message" &&
          (envelope.payload as { messageId?: string }).messageId === "concurrent-b",
      );

      assert.ok(first.sequence !== undefined);
      assert.ok(second.sequence !== undefined);
      assert.ok(second.sequence! > first.sequence!);
    });
  });
});

test("disconnect triggers idle offload after timer elapses", async () =>
{
  const timers = CreateFakeTimers();

  await WithWebSocketTestServer(async (handle) =>
  {
    const session = await CreateBlankSessionViaApi(handle);
    const url = BuildWsUrl(handle, session.pile, session.sessionId, { clientId: "idle-client" });
    const socket = await import("./helpers.js").then((mod) => mod.ConnectWebSocket(url));

    await CollectEnvelopesUntil(socket, "server.caught_up");
    socket.close();

    await new Promise((resolve) => setTimeout(resolve, 20));

    const statusBefore = handle.agentManager.getStatus({
      pile: session.pile,
      sessionId: session.sessionId,
    });
    assert.ok(statusBefore);
    assert.equal(statusBefore?.connectedClientCount, 0);

    timers.Advance(1500);

    await new Promise((resolve) => setTimeout(resolve, 20));

    const statusAfter = handle.agentManager.getStatus({
      pile: session.pile,
      sessionId: session.sessionId,
    });

    assert.equal(statusAfter, null);
  }, { idleOffloadSeconds: 1, timers });
});

