      SendClientFrame(
        socket,
        CreateClientEnvelope(
          "client.history_request",
          session.pile,
          session.sessionId,
          {
            after: 1,
            limit: 10,
            prefer: "events",
          },
          "history-after",
        ),
      );

      const afterPage = await WaitForEnvelope(
        socket,
        (envelope) =>
