    await WithWebSocket(url, async (socket) =>
    {
      await CollectEnvelopesUntil(socket, "server.caught_up");

      SendClientFrame(
        socket,
        CreateClientEnvelope(
          "client.model_select",
          session.pile,
          session.sessionId,
          {
            provider: model.provider,
            id: model.id,
            applyTo: "next_turn",
