    const connected = await ConnectWebSocket(url);
    const socket = connected.socket;

    try
    {
      await DrainConnection(socket);

      SendClientFrame(
        socket,
        CreateClientEnvelope(
          "client.history_request",
          session.pile,
          session.sessionId,
          {
