        },
      });
    }

    const url = BuildWsUrl(handle, session.pile, session.sessionId);
    const connected = await ConnectWebSocket(url);
    const socket = connected.socket;

    try
    {
      await DrainConnection(socket);

      SendClientFrame(
        socket,
        CreateClientEnvelope(
          "client.history_request",
          session.pile,
          session.sessionId,
          {
            before: 5,
            limit: 50,
            prefer: "events",
          },
        ),
      );

      SendClientFrame(
        socket,
        CreateClientEnvelope(
